/* From Uiverse.io by PriyanshuGupta28 - Tags: loader, 3d loader, 3d cude loader */
.__UIV_SCOPE__ .loader {
  display: flex;
  justify-content: center;
  align-items: center;
  height: 100%;
}

.__UIV_SCOPE__ .cube {
  width: 100px;
  height: 100px;
  position: relative;
  transform-style: preserve-3d;
  animation: spin 2s infinite linear;
}

.__UIV_SCOPE__ .side {
  position: absolute;
  width: 100px;
  height: 100px;
  opacity: 0.8;
}

.__UIV_SCOPE__ .front {
  transform: translateZ(50px);
  background: linear-gradient(45deg, #ff4e50, #f9d423);
}

.__UIV_SCOPE__ .back {
  transform: translateZ(-50px);
  background: linear-gradient(45deg, #40e0d0, #ff8c00);
}

.__UIV_SCOPE__ .top {
  transform: rotateX(90deg) translateZ(50px);
  background: linear-gradient(45deg, #800080, #00bfff);
}

.__UIV_SCOPE__ .bottom {
  transform: rotateX(90deg) translateZ(-50px);
  background: linear-gradient(45deg, #008000, #ffff00);
}

.__UIV_SCOPE__ .left {
  transform: rotateY(90deg) translateZ(50px);
  background: linear-gradient(45deg, #0000ff, #ff1493);
}

.__UIV_SCOPE__ .right {
  transform: rotateY(90deg) translateZ(-50px);
  background: linear-gradient(45deg, #00ffff, #ff0000);
}

@keyframes spin {
  0% {
    transform: rotateX(0deg) rotateY(0deg);
  }

  100% {
    transform: rotateX(360deg) rotateY(360deg);
  }
}
